_get($font-sizes, 0) !default;\n\n/* ----------------------------- Phoenix-buttons ---------------------------- */\n$btn-phoenix-border-color: var(--#{$prefix}gray-200);\n\n//*-----------------------------------------------\n//|   Buttons and Forms\n//-----------------------------------------------*/\n\n$input-btn-padding-y: 0.625rem !default;\n$input-btn-padding-x: 1.5rem !default;\n\n$input-padding-y-sm: 0.375rem;\n$input-padding-y: 0.5rem;\n$input-padding-y-lg: 0.75rem;\n\n$input-btn-font-size: map-get($font-sizes, '9');\n$input-btn-font-size-sm: map-get($font-sizes, '9');\n$input-btn-font-size-lg: map-get($font-sizes, 8);\n$input-btn-line-height: $line-height-base;\n$input-font-weight: $font-weight-semi-bold;\n\n$input-btn-padding-y-sm: 0.5rem !default;\n$input-btn-padding-x-sm: 1rem !default;\n\n$input-btn-padding-y-lg: 0.875rem !default;\n$input-btn-padding-x-lg: 1.5rem !default;\n\n$input-box-shadow: inset 0 1px 2px transparent !default;\n$btn-reveal-hover-shadow: 0 0 0 1px rgba(43, 45, 80, 0.1),\n  0 2px 5px 0 rgba(43, 45, 80, 0.08), 0 1px 1.5px 0 rgba($black, 0.07),\n  0 1px 2px 0 rgba($black, 0.08) !default;\n$btn-font-weight: $font-weight-medium !default;\n$input-btn-focus-blur: 0 !default;\n$btn-focus-width: 0 !default;\n$btn-focus-box-shadow: 0 0 0 0.25rem transparent !default;\n$btn-active-box-shadow: inset 0 3px 5px rgba($black, 0) !default;\n\n//*-----------------------------------------------\n//|   Forms\n//-----------------------------------------------*/\n\n$input-padding-x: 1rem;\n$input-padding-x-lg: 1rem;\n\n$input-disabled-bg: rgba(var(--#{$prefix}gray-100-rgb), 0.7) !default;\n$input-disabled-color: var(--#{$prefix}gray-500) !default;\n$input-group-addon-bg: $gray-100 !default;\n$input-disabled-group-addon-bg: $input-disabled-bg !default;\n$input-disabled-group-addon-color: $input-disabled-color !default;\n$input-border-color: var(--#{$prefix}input-border-color) !default;\n$input-color: var(--#{$prefix}gray-900) !default;\n$input-placeholder