//phoenix-react/./src/assets/scss/theme/_setting-panel.scss","webpack://phoenix-react/./src/assets/scss/theme/_showcase.scss","webpack://phoenix-react/./src/assets/scss/theme/_calendar.scss","webpack://phoenix-react/./src/assets/scss/theme/_chat.scss","webpack://phoenix-react/./src/assets/scss/theme/_typing.scss","webpack://phoenix-react/./src/assets/scss/theme/_crm.scss","webpack://phoenix-react/./src/assets/scss/theme/_auth-card.scss","webpack://phoenix-react/./src/assets/scss/theme/_pricing.scss"],"sourcesContent":["/* -------------------------------------------------------------------------- */\r\n/*                                 Theme                                      */\r\n/* -------------------------------------------------------------------------- */\r\n\r\n@import '~bootstrap/scss/_functions';\r\n@import 'theme/functions';\r\n\r\n@import 'user-variables';\r\n@import 'theme/variables';\r\n\r\n@import 'theme/maps';\r\n@import '~bootstrap/scss/maps';\r\n\r\n@import '~bootstrap/scss/mixins';\r\n@import 'theme/mixins';\r\n\r\n@import 'theme/_utilities';\r\n@import '~bootstrap/scss/variables';\r\n// @import '~bootstrap/scss/root';\r\n@import 'theme/root';\r\n\r\n/*-----------------------------------------------\r\n|   Bootstrap Styles\r\n-----------------------------------------------*/\r\n@import 'bootstrap';\r\n\r\n/*-----------------------------------------------\r\n|   Theme Styles\r\n-----------------------------------------------*/\r\n@import 'theme/theme';\r\n","/* prettier-ignore */\r\n@use 'sass:math';\r\n@import 'colors';\r\n$prefix: 'phoenix-';\r\n// Grid containers\r\n//\r\n// Define the maximum width of `.container` for different screen sizes.\r\n// scss-docs-start container-max-widths\r\n$container-max-widths: () !default;\r\n$container-max-widths: map-merge(\r\n  (\r\n    sm: 540px,\r\n    md: 720px,\r\n    lg: 960px,\r\n    xl: 1184px,\r\n    xxl: 1678px\r\n  ),\r\n  $container-max-widths\r\n);\r\n\r\n$container-small-max-widths: (\r\n  sm: 540px,\r\n  md: 720px,\r\n  lg: 960px,\r\n  xl: 1216px\r\n);\r\n\r\n$grid-breakpoints: () !default;\r\n$grid-breakpoints: map-merge(\r\n  (\r\n    xs: 0,\r\n    sm: 576px,\r\n    md: 768px,\r\n    lg: 992px,\r\n    xl: 1200px,\r\n    xxl: 1540px\r\n  ),\r\n  $grid-breakpoints\r\n);\r\n\r\n//*-----------------------------------------------\r\n//|   Gutter\r\n//-----------------------------------------------*/\r\n$grid-gutter-width: 2rem !default;\r\n\r\n// Customize the light and dark text colors for use in our color contrast function.\r\n// $color-contrast-dark: $gray-800 !default;\r\n$color-contrast-dark: $black !default;\r\n$color-contrast-light: $white !default;\r\n\r\n// Min contrast ratio\r\n$min-contrast-ratio: 2 !default;\r\n\r\n//*-----------------------------------------------\r\n//|   Brand colors\r\n//-----------------------------------------------*/\r\n$linkedin: #0077b5 !default;\r\n$facebook: #3c5a99 !default;\r\n$twitter: #1da1f2 !default;\r\n$google-plus: #dd4b39 !default;\r\n$github: #333333 !default;\r\n$youtube: #ff0001 !default;\r\n\r\n$brand-colors: () !default;\r\n$brand-colors: map-merge(\r\n  (\r\n    'facebook': $facebook,\r\n    'google-plus': $google-plus,\r\n    'twitter': $twitter,\r\n    'linkedin': $linkedin,\r\n    'youtube': $youtube,\r\n    'github': $github\r\n  ),\r\n  $brand-colors\r\n);\r\n\r\n//*-----------------------------------------------\r\n//|   Border\r\n//-----------------------------------------------*/\r\n$border-width: 1px !default;\r\n$border-color: var(--#{$prefix}gray-200);\r\n\r\n// Options\r\n//\r\n// Quickly modify global styling by enabling or disabling optional features.\r\n\r\n$enable-shadows: true !default;\r\n$enable-negative-margins: true !default;\r\n\r\n// $component-active-color: var(--#{$prefix}white) !default;\r\n// $component-active-bg: var(--#{$prefix}primary) !default;\r\n\r\n//*-----------------------------------------------\r\n//|   Shadow\r\n//-----------------------------------------------*/\r\n$box-shadow: 0px 2px 4px -2px rgba(36, 40, 46, 0.08);\r\n// $box-shadow-sm: 0px 2px 4px -2px rgba(36, 40, 46, 0.08);\r\n// $box-shadow-lg: var(--#{$prefix}box-shadow-lg) !default;\r\n// $box-shadow-inset: 0px 0px 0px 4px rgba(56, 116, 255, 0.2) !default;\r\n$box-shadow-gray-400: 0px 4px 8px -6px rgba(36, 40, 46, 0.03),\r\n  0px 16px 8px -4px rgba(36, 40, 46, 0.03);\r\n\r\n//*-----------------------------------------------\r\n//|   Spacing\r\n//----------------------------------------------\r\n\r\n$spacer: 1rem !default;\r\n$spacers: () !default;\r\n\r\n$spacers: map-merge(\r\n  (\r\n    0: 0,\r\n    1: $spacer * 0.25,\r\n    2: $spacer * 0.5,\r\n    3: $spacer,\r\n    4: $spacer * 1.5,\r\n    5: $spacer * 2,\r\n    6: $spacer * 2.5,\r\n    7: $spacer * 3,\r\n    8: $spacer * 3.5,\r\n    9: $spacer * 4,\r\n    10: $spacer * 4.5,\r\n    11: $spacer * 5,\r\n    12: $spacer * 6,\r\n    13: $spacer * 6.5,\r\n    14: $spacer * 7,\r\n    15: $spacer * 7.5\r\n  ),\r\n  $spacers\r\n);\r\n\r\n//*-----------------------------------------------\r\n//|   Body\r\n//-----------------------------------------------*/\r\n$body-bg: $gray-soft !default;\r\n$body-color: $gray-900 !default;\r\n\r\n//*-----------------------------------------------\r\n//|   Link\r\n//-----------------------------------------------*/\r\n$link-decoration: none !default;\r\n$link-hover-decoration: underline !default;\r\n\r\n//*-----------------------------------------------\r\n//|   Components\r\n//-----------------------------------------------*/\r\n$border-radius-sm: 0.25rem !default;\r\n$border-radius: 0.375rem !default;\r\n$border-radius-lg: 0.5rem !default;\r\n\r\n//*-----------------------------------------------\r\n//|   Fonts Families\r\n//-----------------------------------------------*/\r\n$font-family-sans-serif: 'Nunito Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,\r\n  'Helvetica Neue', Arial, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol' !default;\r\n$font-family-monospace: 'SFMono-Regular', Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New',\r\n  monospace !default;\r\n$font-family-base: $font-family-sans-serif;\r\n\r\n//*-----------------------------------------------\r\n//|   Fonts\r\n//-----------------------------------------------*/\r\n$type-scale: 1.25 !default;\r\n$font-size-base: 1rem !default;\r\n$font-sizes: (\r\n  '11': math.div(1, pow($type-scale, 3)) * $font-size-base,\r\n  // 8.19px\r\n  '10': math.div(1, pow($type-scale, 2)) * $font-size-base,\r\n  // 10.24px\r\n  '9': math.div(1, $type-scale) * $font-size-base,\r\n  // 12.80px\r\n  8: $font-size-base,\r\n  // 16px\r\n  7: pow($type-scale, 1) * $font-size-base,\r\n  //20px\r\n  6: pow($type-scale, 2) * $font-size-base,\r\n  //25px\r\n  5: pow($type-scale, 3) * $font-size-base,\r\n  // 31.25px\r\n  4: pow($type-scale, 4) * $font-size-base,\r\n  // 39.06px\r\n  3: pow($type-scale, 5) * $font-size-base,\r\n  // 48.83px\r\n  2: pow($type-scale, 6) * $font-size-base,\r\n  // 61.04px\r\n  1: pow($type-scale, 7) * $font-size-base // 76.29px\r\n) !default;\r\n\r\n$font-size-sm: $font-size-base * 0.875 !default;\r\n$font-size-lg: $font-size-base * 1.2 !default;\r\n$font-weight-thin: 100 !default;\r\n$font-weight-lighter: 200 !default;\r\n$font-weight-light: 300 !default;\r\n$font-weight-normal: 400 !default;\r\n$font-weight-medium: 500 !default;\r\n$font-weight-semi-bold: 600 !default;\r\n$font-weight-bold: 700 !default;\r\n$font-weight-bolder: 800 !default;\r\n$font-weight-black: 900 !default;\r\n\r\n$line-height-base: 1.49 !default;\r\n$line-height-sm: 1.2 !default;\r\n$line-height-lg: 1.4 !default;\r\n\r\n$h1-font-size: map_get($font-sizes, 4) !default;\r\n$h2-font-size: map_get($font-sizes, 5) !default;\r\n$h3-font-size: map_get($font-sizes, 6) !default;\r\n$h4-font-size: map_get($font-sizes, 7) !default;\r\n$h5-font-size: map_get($font-sizes, 8) !default;\r\n$h6-font-size: map_get($font-sizes, '9') !default;\r\n\r\n$headings-font-family: $font-family-sans-serif !default;\r\n$headings-font-weight: $font-weight-bold !default;\r\n$headings-color: var(--#{$prefix}1100) !default;\r\n$headings-line-height: 1 !default;\r\n$headings-margin-bottom: map-get($spacers, 1) !default;\r\n\r\n// scss-docs-start display-headings\r\n$display-font-sizes: () !default;\r\n$display-font-sizes: map-merge(\r\n  (\r\n    1: map_get($font-sizes, 1),\r\n    2: map_get($font-sizes, 2),\r\n    3: map_get($font-sizes, 3),\r\n    4: map_get($font-sizes, 4),\r\n    5: map_get($font-sizes, 5),\r\n    6: map_get($font-sizes, 6)\r\n  ),\r\n  $display-font-sizes\r\n);\r\n\r\n$display-font-weight: $font-weight-normal !default;\r\n// scss-docs-end display-headings\r\n\r\n$lead-font-size: map-get($font-sizes, 7) !default;\r\n$lead-font-weight: $font-weight-semi-bold !default;\r\n\r\n$small-font-size: 75% !default;\r\n\r\n$text-muted: $gray-500 !default;\r\n\r\n$blockquote-font-size: $font-size-lg !default;\r\n\r\n//*-----------------------------------------------\r\n//|   Accordion\r\n//-----------------------------------------------*/\r\n// $accordion-icon-active-color: $body-color;\r\n$accordion-padding-y: map-get($spacers, 2) !default;\r\n$accordion-padding-x: 0 !default;\r\n$accordion-border-radius: 0 !default;\r\n$accordion-bg: transparent !default;\r\n$accordion-color: $gray-1000 !default;\r\n$accordion-button-active-bg: transparent !default;\r\n$accordion-border-width: 0 !default;\r\n$accordion-button-color: $primary !default;\r\n$accordion-button-active-color: $gray-1100 !default;\r\n$accordion-icon-color: $primary !default;\r\n$accordion-icon-active-color: $primary !default;\r\n$accordion-button-icon: url(\"data:image/svg+xml,%3Csvg aria-hidden='true' focusable='false' role='img' xmlns='http://www.w3.org/2000/svg' viewBox='-200 -200 900 900'%3E%3Cpath fill='#{$accordion-icon-color}' d='M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32